"""Meta.ai chat - simple reliable client (plain input loop).

SINGLE-FILE build: embedded .proto descriptors + token materialize into
./_rt on first run. Token priority: env META_TOKEN -> ./token.txt ->
embedded fallback. Type a message, get a streamed reply.
/mode thinking|instant · /new · /img <p> · /upload <file> · /quit
"""
import re, time, uuid, base64, os, json, sys, random, threading, asyncio, io
