ROOT_DIR = os.path.dirname(os.path.abspath(__file__))

# ── embedded files (materialize once into ./_rt) ────────────────────────
_PAYLOADS = {
    "ecto_request_client.proto": r"""""",
    "ecto_response_client.proto": r"""""",
    "token.txt": r"""""",
}

def _bootstrap():
    _rt = os.path.join(ROOT_DIR, "_rt")
    os.makedirs(_rt, exist_ok=True)
    for name, b64 in _PAYLOADS.items():
        dst = os.path.join(_rt, name)
        if not os.path.exists(dst) or os.path.getsize(dst) < 32:
            try:
                open(dst, "wb").write(base64.b64decode(b64))
            except Exception as e:  # noqa: BLE001
                print(f"[!] failed to materialize {name}: {e}")
    sys.path.insert(0, _rt)

_bootstrap()

# ── module proxies: `import dgw_client` / `from dgw_session import X` ────
class _ModuleProxy(type(sys)):
    def __getattr__(self, name):
        g = globals()
        if name in g:
            return g[name]
        raise AttributeError(name)

for _m in ("dgw_client", "dgw_session"):
    sys.modules[_m] = _ModuleProxy(_m)

def load_token():
    """Token priority: env META_TOKEN -> ./token.txt -> embedded fallback."""
    t = os.environ.get("META_TOKEN", "").strip()
    if t:
        return t
    tf = os.path.join(ROOT_DIR, "token.txt")
    if os.path.exists(tf):
        t = open(tf, encoding="utf-8").read().strip()
        if t:
            return t
    b64 = _PAYLOADS.get("token.txt") or ""
    if b64:
        try:
            return base64.b64decode(b64.encode()).decode("utf-8").strip()
        except Exception:  # noqa: BLE001
            pass
    return ""




