# ── proto descriptor pools ────────────────────────────────────────────
def pool_from(desc_path, deps=()):
    fd = descriptor_pb2.FileDescriptorProto()
    with open(desc_path, "rb") as f:
        fd.ParseFromString(f.read())
    pool = descriptor_pool.DescriptorPool()
    for d in deps:
        fd2 = descriptor_pb2.FileDescriptorProto()
        with open(d, "rb") as f:
            fd2.ParseFromString(f.read())
        pool.Add(fd2)
        # declare the dependency so cross-file type resolution works
        bn = os.path.basename(d)
        if bn not in fd.dependency:
            fd.dependency.append(bn)
    pool.Add(fd)
    return pool

req_pool = pool_from(os.path.join(HERE, "ecto_request_client.proto"))
resp_pool = pool_from(os.path.join(HERE, "ecto_response_client.proto"),
                      deps=[os.path.join(HERE, "ecto_request_client.proto")])

ReqCls = message_factory.GetMessageClass(req_pool.FindMessageTypeByName("clippy.ecto.Request"))
RespCls = message_factory.GetMessageClass(resp_pool.FindMessageTypeByName("clippy.ecto.Response"))

