def make_estab_frame(conversation_id):
    payload = json.dumps({
        "x-dgw-app-x-ecto-conversation-id": conversation_id,
        "x-dgw-app-client-payload-type": "PROTO_INSIDE_JSON"
    }).encode()
    # type 0x0f, sid 0, len(3 LE), payload
    return b"\x0f" + b"\x00\x00" + len(payload).to_bytes(3, "little") + payload

def make_data_frame(request_id, proto_bytes):
    inner = json.dumps({
        "req-id": request_id,
        "payload": base64.b64encode(proto_bytes).decode()
    }).encode()
    # type 0x0d, sid 0, len(3 LE) = 2 flag bytes + inner, flags 00 80, inner
    return b"\x0d" + b"\x00\x00" + (len(inner) + 2).to_bytes(3, "little") + b"\x00\x80" + inner

def parse_recv_frame(data):
    """Return (frame_type, sid, flags, payload)."""
    ftype = data[0]
    if len(data) == 1:
        return ftype, 0, b"", b""
    sid = data[1] | (data[2] << 8)
    ln = data[3] | (data[4] << 8) | (data[5] << 16)
    body = data[6:6+ln]
    return ftype, sid, body, body  # flags+payload both in body; caller slices

def download_media_items(media, out_dir=None):
    """Download media URLs using session cookies. Returns list with 'saved' paths."""
    if out_dir is None:
        out_dir = os.path.join(ROOT, "downloads")
    os.makedirs(out_dir, exist_ok=True)
    try:
        from curl_cffi import requests as cffi_requests
    except ImportError:
        print("[!] curl_cffi not available, cannot download media")
        return media
    try:
        cookies = json.load(open(os.path.join(ROOT, "meta_session.json")))
        ck = {c["name"]: c["value"] for c in cookies}
    except Exception as e:
        print(f"[!] no cookies for download: {e}")
        ck = {}
    s = cffi_requests.Session(impersonate="chrome")
    s.cookies.update(ck)
    for m in media:
        url = m.get("url")
        if not url or not url.startswith("http"):
            m["saved"] = None
            continue
        try:
            r = s.get(url, timeout=90)
            if r.status_code == 200:
                fname = os.path.basename(m.get("filename") or "") or "media"
                if not fname or fname == "media" or "/" in fname or "\\" in fname:
                    fname = "media_" + str(abs(hash(url)))[:10]
                    ext = {
                        "image/webp": ".webp", "image/jpeg": ".jpg", "image/png": ".png",
                        "image/gif": ".gif", "image/svg+xml": ".svg", "image/bmp": ".bmp",
                        "image/tiff": ".tiff", "image/x-icon": ".ico", "image/heic": ".heic",
                        "image/avif": ".avif",
                        "video/mp4": ".mp4", "video/webm": ".webm", "video/x-matroska": ".mkv",
                        "video/quicktime": ".mov", "video/mpeg": ".mpg", "video/x-msvideo": ".avi",
                        "audio/mpeg": ".mp3", "audio/mp4": ".m4a", "audio/wav": ".wav",
                        "audio/ogg": ".ogg", "audio/aac": ".aac", "audio/flac": ".flac",
                        "audio/webm": ".weba",
                        "text/plain": ".txt", "text/csv": ".csv", "text/x-srt": ".srt",
                        "application/x-subrip": ".srt", "text/vtt": ".vtt",
                        "text/html": ".html", "text/markdown": ".md", "text/xml": ".xml",
                        "application/json": ".json", "application/xml": ".xml",
                        "application/yaml": ".yaml", "application/javascript": ".js",
                        "application/pdf": ".pdf", "application/zip": ".zip",
                        "application/gzip": ".gz", "application/x-tar": ".tar",
                        "application/epub+zip": ".epub", "application/rtf": ".rtf",
                        "application/vnd.openxmlformats-officedocument.wordprocessingml.document": ".docx",
                        "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet": ".xlsx",
                        "application/vnd.openxmlformats-officedocument.presentationml.presentation": ".pptx",
                        "application/msword": ".doc", "application/vnd.ms-excel": ".xls",
                    }.get(m.get("mime_type"), "")
                    fname += ext
                fname = os.path.basename(fname.replace("\\", "/"))
                fp = os.path.join(out_dir, fname)
                open(fp, "wb").write(r.content)
                m["saved"] = fp
                m["size"] = len(r.content)
                if m.get("mime_type", "").lower() in (
                        "text/plain", "text/csv", "text/html", "text/markdown",
                        "text/vtt", "application/x-subrip", "text/x-srt",
                        "application/json", "application/xml", "application/rtf"):
                    if len(r.content) < 300_000:
                        try:
                            m["preview"] = r.content.decode("utf-8", "replace")
                        except Exception:
                            pass
                print(f"[*] saved {fp} ({len(r.content)} bytes)")
            else:
                m["saved"] = None
                print(f"[!] download failed status {r.status_code}")
        except Exception as e:
            m["saved"] = None
            print(f"[!] download error {e}")
    return media

async def send_dgw(conversation_id, message, token, timeout=90, download_media=False, mode="instant"):
    request_id = str(uuid.uuid4())
    proto = build_request(conversation_id, message, request_id, mode=mode)

    from urllib.parse import quote
    token_b64 = quote("ecto1:" + token, safe="")
    ws_url = (
        "wss://gateway.meta.ai/ws/clippy?"
        "x-dgw-appid=1522763855472543&x-dgw-appversion=1.0.0&"
        "x-dgw-authtype=15%3A0&x-dgw-version=5&x-dgw-uuid=0&x-dgw-tier=prod&"
        f"Authorization={token_b64}&x-dgw-app-origin=meta.ai&"
        f"x-dgw-app-clippy-request-id={uuid.uuid4()}"
    )
    estab = make_estab_frame(conversation_id)
    data_fr = make_data_frame(request_id, proto)

    print(f"[*] connecting DGW, req-id {request_id}")
    async with websockets.connect(
            ws_url, max_size=10_000_000, ping_interval=None,
            origin="https://www.meta.ai") as ws:
        await ws.send(estab)
        first = await asyncio.wait_for(ws.recv(), 15)
        print(f"[*] estab reply: {len(first)} bytes {first[:30].hex()}")
        if first[:1] == b"\x0f":
            print("    estab status:", first[6:])
        ack = await asyncio.wait_for(ws.recv(), 15)
        print(f"[*] ack frame: {ack.hex()}")

        await ws.send(data_fr)
        print("[*] sent data frame, waiting for response...")

        full_text = ""
        media = []
        last_reasoning = ""
        while True:
            raw = await asyncio.wait_for(ws.recv(), timeout)
            if isinstance(raw, str):
                print("[ws-text]", raw[:200]); continue
            ftype = raw[0]
            if ftype == 0x0d:
                proto_bytes = raw[8:]
                try:
                    resp = RespCls()
                    resp.ParseFromString(proto_bytes)
                    piece = resp.piece
                    if piece.HasField("model_response"):
                        mr = piece.model_response
                        if mr.raw_chunk:
                            full_text += mr.raw_chunk
                            print(mr.raw_chunk, end="", flush=True)
                        if mr.is_final_chunk:
                            print()
                            print("[*] final chunk received")
                    if piece.HasField("reasoning_response"):
                        rdelta = piece.reasoning_response.delta
                        if rdelta:
                            new_part = rdelta[len(last_reasoning):] if rdelta.startswith(last_reasoning) else rdelta
                            last_reasoning = rdelta
                            if new_part:
                                print(f"\x1b[90m{new_part}\x1b[0m", end="", flush=True)
                    if piece.HasField("tool_output"):
                        for att in piece.tool_output.attachments:
                            rec = {
                                "type": att.type,
                                "mime_type": att.mime_type,
                                "filename": att.filename,
                                "url": att.urls.cdn_url_original or att.urls.permanent_url,
                            }
                            media.append(rec)
                            print(f"\n[media] {att.type} {att.mime_type} {att.filename}")
                            print(f"[media] {rec['url']}")
                    if piece.HasField("async_ack"):
                        print("[*] async ack:", piece.async_ack.accepted)
                    if resp.is_final_chunk:
                        print("[*] isFinalChunk -> done")
                        # wait a moment for any trailing frames
                        await asyncio.sleep(1.0)
                        try:
                            while True:
                                extra = await asyncio.wait_for(ws.recv(), 0.5)
                                if isinstance(extra, bytes) and extra[0] == 0x0d:
                                    e2 = RespCls(); e2.ParseFromString(extra[8:])
                                    if e2.piece.HasField("model_response") and e2.piece.model_response.raw_chunk:
                                        full_text += e2.piece.model_response.raw_chunk
                                        print(e2.piece.model_response.raw_chunk, end="", flush=True)
                        except asyncio.TimeoutError:
                            pass
                        break
                    if resp.is_final_model_chunk:
                        print()
                        print("[*] isFinalModelChunk -> done")
                        await asyncio.sleep(1.0)
                        try:
                            while True:
                                extra = await asyncio.wait_for(ws.recv(), 0.5)
                                if isinstance(extra, bytes) and extra[0] == 0x0d:
                                    e2 = RespCls(); e2.ParseFromString(extra[8:])
                                    if e2.piece.HasField("model_response") and e2.piece.model_response.raw_chunk:
                                        full_text += e2.piece.model_response.raw_chunk
                                        print(e2.piece.model_response.raw_chunk, end="", flush=True)
                        except asyncio.TimeoutError:
                            pass
                        break
                except Exception as e:
                    print(f"[parse err] {e}")
            elif ftype == 0x0c:
                pass
            elif ftype == 0x0a:
                pass
            else:
                print(f"[frame 0x{ftype:02x}] {raw[:40].hex()}")
    if download_media and media:
        media = download_media_items(media)
    return full_text, media

# ── dgw_session (merged) ─────────────────────────────────────
"""Persistent DGW WebSocket client — connects ONCE, streams many messages over one socket.

This is the big speed win: the old flow did TLS + WS handshake + estab + ack per
message (~1-2s overhead each time). Here the socket stays open and each message
is just one data frame + streamed response.
"""
import asyncio, base64, json, os, random, struct, sys, time, uuid
from urllib.parse import quote

import websockets
from google.protobuf import json_format



class DGWError(Exception):
    pass


class DGWSession:
    """One websocket, many messages. Use from a single async task."""

    def __init__(self, token, conversation_id, download_media=True, out_dir=None):
        if ":" in token:
            token = token.split(":", 1)[1]
        self.token = token
        self.conversation_id = conversation_id
        self.download_media = download_media
        self.out_dir = out_dir
        self._ws = None

    @property
    def _ws_open(self):
        try:
            return self._ws is not None and self._ws.state.name == "OPEN"
        except Exception:
            return self._ws is not None

    # ── connection ────────────────────────────────────────────────────
    def _url(self):
        token_b64 = quote("ecto1:" + self.token, safe="")
        return (
            "wss://gateway.meta.ai/ws/clippy?"
            "x-dgw-appid=1522763855472543&x-dgw-appversion=1.0.0&"
            "x-dgw-authtype=15%3A0&x-dgw-version=5&x-dgw-uuid=0&x-dgw-tier=prod&"
            f"Authorization={token_b64}&x-dgw-app-origin=meta.ai&"
            f"x-dgw-app-clippy-request-id={uuid.uuid4()}"
        )

    async def connect(self, timeout=20):
        """Open socket + estab handshake. Safe to call if already open."""
        if self._ws_open:
            return
        try:
            self._ws = await asyncio.wait_for(
                websockets.connect(
                    self._url(), max_size=10_000_000, ping_interval=None,
                    origin="https://www.meta.ai"),
                timeout=12)
        except asyncio.TimeoutError:
            raise DGWError("connect timed out")
        await self._ws.send(make_estab_frame(self.conversation_id))
        # server may send an initial ack (0x0a) then the estab reply (0x0f),
        # possibly with heartbeat frames (0x0c) in between
        for _ in range(4):
            first = await asyncio.wait_for(self._ws.recv(), 15)
            if isinstance(first, str):
                continue
            if first[:1] == b"\x0f":
                return
            if first[:1] in (b"\x0a", b"\x0c"):
                continue
        raise DGWError(f"estab: no 0x0f confirmation")

    async def close(self):
        if self._ws is not None:
            try:
                await self._ws.close()
            except Exception:
                pass
            self._ws = None

    # ── messaging ─────────────────────────────────────────────────────
    async def ask(self, message, mode="instant", on_chunk=None, on_reasoning=None,
                  on_media=None, timeout=180, attachments=None):
        """Send one message, stream response. Returns (full_text, media_list)."""
        request_id = str(uuid.uuid4())
        proto = build_request(self.conversation_id, message, request_id, mode=mode,
                              attachments=attachments)
        data_fr = make_data_frame(request_id, proto)

        if not self._ws_open:
            await self.connect()

        await self._ws.send(data_fr)

        full_text = ""
        media = []
        last_reasoning = ""
        seen_media = set()

        async def _drain_tail():
            """Scoop any trailing frames after final chunk, until quiet."""
            quiet = 0
            while True:
                try:
                    extra = await asyncio.wait_for(self._ws.recv(), 0.3)
                except asyncio.TimeoutError:
                    quiet += 1
                    if quiet >= 3:
                        return
                    continue
                except Exception:
                    return
                quiet = 0
                if isinstance(extra, bytes) and extra[0] == 0x0d:
                    e2 = RespCls()
                    e2.ParseFromString(extra[8:])
                    piece = e2.piece
                    if piece.HasField("model_response") and piece.model_response.raw_chunk:
                        c = piece.model_response.raw_chunk
                        nonlocal full_text
                        full_text += c
                        if on_chunk:
                            on_chunk(c)
                    if piece.HasField("tool_output"):
                        for att in piece.tool_output.attachments:
                            _emit_att(att, media, on_media)
                    if e2.is_final_chunk or e2.is_final_model_chunk:
                        quiet = 0

        def _emit_att(att, media, on_media):
            url = att.urls.cdn_url_original or att.urls.permanent_url
            rec = {
                "type": att.type,
                "mime_type": att.mime_type,
                "filename": att.filename,
                "url": url,
            }
            key = url or (att.mime_type, att.filename)
            if key in seen_media:
                return ()
            seen_media.add(key)
            media.append(rec)
            if on_media:
                on_media(rec)
            return ()

        while True:
            raw = await asyncio.wait_for(self._ws.recv(), timeout)
            if isinstance(raw, str):
                continue
            ftype = raw[0]
            if ftype == 0x0c:
                continue  # ping/pong heartbeat
            if ftype != 0x0d:
                continue
            proto_bytes = raw[8:]
            resp = RespCls()
            resp.ParseFromString(proto_bytes)
            piece = resp.piece

            if piece.HasField("model_response"):
                mr = piece.model_response
                if mr.raw_chunk:
                    full_text += mr.raw_chunk
                    if on_chunk:
                        on_chunk(mr.raw_chunk)
                if mr.is_final_chunk:
                    pass

            if piece.HasField("reasoning_response"):
                rdelta = piece.reasoning_response.delta
                if rdelta:
                    new_part = (rdelta[len(last_reasoning):]
                                if rdelta.startswith(last_reasoning) else rdelta)
                    last_reasoning = rdelta
                    if new_part and on_reasoning:
                        on_reasoning(new_part)

            if piece.HasField("tool_output"):
                for att in piece.tool_output.attachments:
                    _emit_att(att, media, on_media)

            if resp.is_final_model_chunk:
                await _drain_tail()
                break

            # is_final_chunk alone is an EARLY marker (empty chunk) that the
            # server sends while the model is still thinking on slow
            # responses — it is NOT the end. Breaking here truncated the
            # reply; the postponed answer was read by the NEXT ask().
            if resp.is_final_chunk:
                if not full_text.strip():
                    continue
                await _drain_tail()
                break

        if self.download_media and media:
            media = download_media_items(media, self.out_dir)

        if not full_text.strip() and not media:
            raise DGWError("empty response (no text, no media) — will retry on a fresh socket")

        return full_text, media


