def save(s):
    json.dump([{"name": c.name, "value": c.value, "domain": c.domain, "path": c.path,
                "secure": c.secure, "expires": c.expires} for c in s.cookies.jar],
              open(SESSION_FILE, "w"), indent=2)

def load():
    if not os.path.exists(SESSION_FILE): return None
    s = requests.Session(impersonate=IMPERSONATE)
    for c in json.load(open(SESSION_FILE)):
        s.cookies.set(c["name"], c["value"], domain=c.get("domain", ".meta.ai"), path=c.get("path", "/"))
    if "ecto_1_sess" not in [c.name for c in s.cookies.jar]:
        os.remove(SESSION_FILE); return None
    return s

