def gql(s, doc_id, variables):
    return s.post(GQL, json={"doc_id": doc_id, "variables": variables}, headers=H())

def create_conversation(s):
    conv_id = str(uuid.uuid4())
    results = {}
    def warmup():
        results["warmup"] = gql(s, DOC_WARMUP, {"conversationId": conv_id})
    def mode():
        results["mode"] = gql(s, DOC_MODE, {"input": {"conversationId": conv_id, "mode": "think_fast"}})
    def check():
        results["check"] = gql(s, DOC_CHECK, {})
    ts = [threading.Thread(target=warmup, daemon=True),
          threading.Thread(target=mode, daemon=True),
          threading.Thread(target=check, daemon=True)]
    for t in ts:
        t.start()
    for t in ts:
        t.join(timeout=10)
    return conv_id

# ═══════════════ DGW SESSION (single socket reused) ═══════════════
class DGWWorker:
    def __init__(self, conv_id):
        self.conv_id = conv_id
        self.events = __import__("queue").Queue()
        self.loop = __import__("asyncio").new_event_loop()
        self.connected = threading.Event()
        self.session = None
        self.thread = threading.Thread(target=self._run, daemon=True)
        self.thread.start()

    def _run(self):
        import asyncio
        asyncio.set_event_loop(self.loop)
        self.loop.run_forever()

    def connect(self):
        import asyncio
        async def _c():
            for attempt in range(3):
                try:
                    from dgw_session import DGWSession
                    token = load_token()
                    self.session = DGWSession(token, self.conv_id, download_media=True)
                    await self.session.connect()
                    self.connected.set()
                    return
                except Exception as e:
                    self.events.put(("ws_error", f"{type(e).__name__}: {e}"))
                    await asyncio.sleep(2)
            self.connected.clear()
        asyncio.run_coroutine_threadsafe(_c(), self.loop)

    def ask(self, message, mode, attachments=None):
        import asyncio
        async def _a():
            try:
                for _ in range(50):
                    if self.session is not None and self.session._ws_open:
                        break
                    await asyncio.sleep(0.3)
                if self.session is None:
                    raise RuntimeError("no session (conversation not ready)")
                if not self.session._ws_open:
                    await self.session.connect()
                    self.connected.set()
                text, media = await self.session.ask(
                    message, mode=mode, attachments=attachments,
                    on_chunk=lambda t: self.events.put(("chunk", t)),
                    on_reasoning=lambda t: self.events.put(("reasoning", t)),
                    on_media=lambda m: self.events.put(("media", m)),
                )
                self.events.put(("done", text, media))
            except Exception as e:
                try:
                    token = load_token()
                    try:
                        await self.session.close()
                    except Exception:
                        pass
                    from dgw_session import DGWSession
                    self.session = DGWSession(token, self.conv_id, download_media=True)
                    await self.session.connect()
                    self.connected.set()
                    text, media = await self.session.ask(
                        message, mode=mode, attachments=attachments,
                        on_chunk=lambda t: self.events.put(("chunk", t)),
                        on_reasoning=lambda t: self.events.put(("reasoning", t)),
                        on_media=lambda m: self.events.put(("media", m)),
                    )
                    self.events.put(("done", text, media))
                except Exception as e2:
                    self.events.put(("error", f"{type(e2).__name__}: {e2}"))
        asyncio.run_coroutine_threadsafe(_a(), self.loop)

    def close(self):
        import asyncio
        async def _c():
            try:
                await self.session.close()
            except Exception:
                pass
            self.loop.stop()
        asyncio.run_coroutine_threadsafe(_c(), self.loop)
        self.thread.join(timeout=3)

    def discard_events(self):
        import queue
        while True:
            try:
                self.events.get_nowait()
            except queue.Empty:
                return

    def reset_session(self):
        """Drop the current socket so stray frames can't leak into the next ask."""
        import asyncio
        async def _c():
            try:
                if self.session is not None:
                    await self.session.close()
            except Exception:
                pass
            self.session = None
            self.connected.clear()
        asyncio.run_coroutine_threadsafe(_c(), self.loop)

# ═══════════════ REPL ═══════════════
def clean_chunk(s):
    """Strip raw citation markers (【123…†L2-L4】) and tidy whitespace."""
    s = re.sub(r"【[^】]*】", "", s)
    s = s.replace("†", "")
    s = re.sub(r"\n{3,}", "\n\n", s)
    return s

def media_kind(m):
    """Friendly label for any attachment mime type."""
    mt = (m.get("mime_type") or "").lower()
    if mt.startswith("image/"):
        return "IMG"
    if mt.startswith("video/"):
        return "VID"
    if mt.startswith("audio/"):
        return "AUD"
    if mt.startswith("text/") or mt in (
            "application/json", "application/xml", "application/x-subrip",
            "application/rtf", "application/x-yaml"):
        return "TXT"
    if "pdf" in mt:
        return "PDF"
    if "wordprocessing" in mt or "spreadsheet" in mt or "presentation" in mt:
        return "DOC"
    if "zip" in mt or "gzip" in mt or "tar" in mt:
        return "ARC"
    return "FILE"

def chat(s):
    mode = "instant"
    show_thinking = False
    print()
    print("=" * 56)
    print("  Meta AI Chat  —  type /help for commands")
    print("=" * 56)
    if s is None:
        print("[*] token-only mode: uuid conversation (no warmup)")
        conv = str(uuid.uuid4())
    else:
        print("[*] creating conversation…")
        conv = create_conversation(s)
    print(f"[*] conversation {conv[:8]}…")
    print("[*] connecting DGW…")
    worker = DGWWorker(conv)
    worker.connect()
    for _ in range(60):
        if worker.connected.is_set():
            print("[*] connected ✓")
            break
        time.sleep(0.2)
    else:
        print("[!] could not connect — check network / token.txt")
    print()

    history = []
    while True:
        try:
            m = input("You: ").strip()
        except (EOFError, KeyboardInterrupt):
            print("\n[*] bye!")
            break
        if not m:
            continue
        if m.lower() == "/quit" or m.lower() == "/exit":
            print("[*] bye!")
            break
        if m.lower() == "/help":
            print("""  /mode thinking|instant   switch reasoning mode
    /think on|off            show/hide the reasoning trace (thinking mode)
  /img <prompt>             generate an image
  /upload <file> [prompt]   attach a file (optional follow-up prompt)
  /new                      start a fresh conversation
  /open <file>              open a downloaded file
  /quit                     exit""")
            continue
        if m.lower() == "/new":
            worker.close()
            conv = (str(uuid.uuid4()) if s is None
                    else create_conversation(s))

            worker = DGWWorker(conv)
            worker.connect()
            print(f"[*] new conversation {conv[:8]}…")
            continue
        if m.lower().startswith("/mode"):
            arg = m.split(maxsplit=1)[1].strip() if len(m.split(maxsplit=1)) > 1 else ""
            if arg and arg in ("thinking", "think"):
                mode = "thinking"; print("[*] mode → THINKING")
            else:
                mode = "instant"; print("[*] mode → INSTANT")
            continue
        if m.lower().startswith("/think"):
            arg = m.split(maxsplit=1)[1].strip() if len(m.split(maxsplit=1)) > 1 else ""
            show_thinking = arg in ("on", "1", "true", "yes")
            print(f"[*] thinking trace → {'ON' if show_thinking else 'OFF'}")
            continue
        if m.lower().startswith("/open"):
            fp = m.split(maxsplit=1)[1].strip() if len(m.split(maxsplit=1)) > 1 else ""
            if fp and os.path.exists(fp):
                os.startfile(os.path.normpath(fp))
                print(f"[*] opened {fp}")
            continue
        if m.lower().startswith("/img"):
            rest = m.split(maxsplit=1)[1].strip() if len(m.split(maxsplit=1)) > 1 else ""
            if not rest:
                print("usage: /img <prompt>")
                continue
            m = "/imagine " + rest

        upload_attachments = None
        if m.lower().startswith("/upload"):
            parts = m.split(maxsplit=1)[1].strip() if len(m.split(maxsplit=1)) > 1 else ""
            if not parts:
                print("usage: /upload <file> [prompt]")
                continue
            fpath, _, prompt = parts.partition(" ")
            fpath = fpath.strip("\"'")
            if not os.path.exists(fpath):
                print(f"[!] no such file: {fpath}")
                continue
            print(f"[*] uploading {fpath}…")
            try:
                from dgw_client import upload_file
                token = load_token()
                import mimetypes
                media_id = upload_file(fpath, token)
                upload_attachments = [{
                    "media_id": media_id,
                    "mime_type": mimetypes.guess_type(fpath)[0] or "application/octet-stream",
                    "filename": os.path.basename(fpath),
                }]
                print(f"[*] uploaded → media_id {media_id}")
            except Exception as e:
                print(f"[!] upload failed: {type(e).__name__}: {e}")
                continue
            m = (prompt.strip() if prompt.strip() else
                 f"Here is a file: {os.path.basename(fpath)}. Please analyze it.")

        history.append(m)
        print("Meta: ", end="", flush=True)
        worker.ask(m, mode, upload_attachments)
        done = None
        last_error = None
        interrupted = False
        thinking_shown = False
        saw_content = False
        spin = ["⠋", "⠙", "⠹", "⠸", "⠼", "⠴", "⠦", "⠧"]
        spin_i = 0
        spin_on = False
        last_act = time.time()
        while done is None and not interrupted:
            try:
                ev = worker.events.get(timeout=0.25)
                last_act = time.time()
                if spin_on:
                    print("\r" + " " * 44 + "\r", end="", flush=True)
                    spin_on = False
            except __import__("queue").Empty:
                idle = time.time() - last_act
                if not saw_content or idle >= 1.5:
                    status = ("thinking…" if (show_thinking or thinking_shown)
                              else "working…")
                    line = f"{spin[spin_i % len(spin)]} {status} {idle:.0f}s"
                    print("\r\x1b[90m" + line.ljust(20) + "\x1b[0m",
                          end="", flush=True)
                    spin_i += 1
                    spin_on = True
                continue
            except KeyboardInterrupt:
                interrupted = True
                if spin_on:
                    print("\r" + " " * 44 + "\r", end="", flush=True)
                worker.reset_session()
                worker.discard_events()
                continue
            if ev[0] == "chunk":
                if not saw_content:
                    print("Meta: ", end="", flush=True)
                    saw_content = True
                text = clean_chunk(ev[1])
                if text:
                    print(text, end="", flush=True)
            elif ev[0] == "reasoning":
                if show_thinking:
                    if not saw_content:
                        print("Meta: ", end="", flush=True)
                        saw_content = True
                    t = clean_chunk(ev[1])
                    if t:
                        print(f"\x1b[90m{t}\x1b[0m", end="", flush=True)
                else:
                    thinking_shown = True
            elif ev[0] == "media":
                if not saw_content:
                    print("Meta: ", end="", flush=True)
                    saw_content = True
                mrec = ev[1]
                name = (mrec.get("filename")
                        or os.path.basename(mrec.get("url") or "") or "attachment")
                print(f"\n[media] {mrec.get('mime_type', '')} {name}")
            elif ev[0] == "done":
                done = ev
                for mi in (ev[2] or []):
                    sp = mi.get("saved")
                    if sp:
                        print(f"\n[{media_kind(mi)}] {sp} ({mi.get('size', '?')} bytes)")
                        pv = mi.get("preview")
                        if pv:
                            pv = " ".join(pv.split())
                            print("   ↳ " + pv[:180])
            elif ev[0] == "error":
                last_error = ev[1]
                done = ev
            elif ev[0] == "ws_error":
                if not saw_content:
                    print("\r" + " " * 44 + "\r", end="", flush=True)
                print(f"\n[ws] {ev[1]}")
        if not saw_content:
            print("\r" + " " * 44 + "\r", end="", flush=True)
            if interrupted:
                print("\n[!] interrupted — current reply discarded")
            elif last_error:
                print(f"\n[!] error: {last_error}")
            else:
                print("[!] empty response")
        else:
            print()
    worker.close()



if __name__ == "__main__":
    # fix Windows stdout encoding (only when actually running the REPL)
    if not (getattr(sys.stdout, "encoding", None) or "").lower().startswith("utf"):
        try:
            sys.stdout = io.TextIOWrapper(sys.stdout.buffer, encoding="utf-8", errors="replace")
        except Exception:
            pass
    print("[i] Meta.ai Chat (simple client)")
    s = load()
    if not s and load_token():
        print("[i] no cookie session - using embedded token (token-only mode)")
    elif not s:
        print("[i] no session, logging in...")
        s = login(EMAIL, PASSWORD)
        if s:
            save(s)
        if not s:
            print("[!] login failed")
            sys.exit(1)
    chat(s)
